// Short analysis exercises complement moves that can be demonstrated in one position.
// Each alternative has its own feedback. Index zero is the solution before shuffling.
function decision(title,goal,facts,options,hint,why,diagram) {
  return {type:"decision",title,goal,facts,options,hint,why,diagram};
}
Object.assign(Drills,{
 hopReply:decision("Test the second hop","Which reply actually breaks your two-jump plan?",[
   ["Your attack","Your hopper has reached the pivot. Its next jump would fill the last liberty."],
   ["Black’s resources","Black can pin the hopper, bring out a remote spider, or move a beetle off a stack in the jumped line, leaving the lower tile in place. The queen stays put."]],
   [["Pin the hopper at its pivot.","A pinned hopper cannot lift for the second jump."],["Place the remote spider.","That placement leaves the jump line and the hopper's mobility intact."],["Change only the top colour of a jumped stack.","A hopper jumps occupied cells of either colour."]],"Check what a hopper needs at take-off and all the way to its landing.","A two-jump threat gives the defender a turn at the pivot. Check for a pin before relying on jump two."),
 gateChoice:decision("Choose an attacker for a gated gap","Which piece can finish this attack immediately?",[
   ["The last liberty","The only ground-level entrance is a closed gate. All other neighbours of the black queen will stay occupied."],
   ["White’s attackers","An ant has a clear run up to the gate. A mobile hopper is lined up to land in the gap. A ground-level beetle is two steps away."]],
   [["The lined-up hopper.","Its first empty landing cell is the final liberty."],["The ant at the entrance.","A longer perimeter route cannot pass the only entrance when it is gated."],["The distant beetle.","It could approach over the hive, but two steps take two turns."]],"Look for a landing that never passes through the entrance at ground level.","A block has to be evaluated against the actual finishers. The straight jump bypasses this gate."),
 ringChoice:decision("Reject a tempting ring","Which consequence decides whether to close this loop?",[
   ["White’s gain","Closing the ring releases two white attackers. Neither can complete a surround this turn."],
   ["Black’s reply","The same ring frees a black hopper with a legal jump into White's final liberty. Leaving the gap open keeps the hopper pinned."]],
   [["Keep the ring open and deny the winning reply.","Black moves first after the proposed ring."],["Close it because White frees more bugs.","Black's one released hopper can end the game before either white attacker moves."],["Close it and move a freed attacker immediately.","Closing the loop uses White's turn."]],"Count the immediate replies before comparing the total number of released bugs.","A ring that frees more of your pieces can still lose at once. The first usable move matters."),
 strength1:decision("Match bugs to gaps","Can White finish with the mobile attackers already committed?",[
   ["Black queen","Two liberties remain. One is open to sliding pieces. The other is behind a closed gate."],
   ["White’s force","Two mobile ants outside the ring can reach the open liberty. Neither can reach the gated one. Black has no forced move into either space."]],
   [["A different attacker or a change to the gate is needed.","The ants compete for one usable gap."],["Yes, the two ants match the two liberties.","Counting pieces alone overlooks that both ants reach the same gap."],["Yes, filling the open liberty automatically opens the gate.","Adding a bug does not remove either occupied flank."]],"Match each attacker to a different liberty it can legally fill.","Strength depends on accessible destinations. A reserve hopper with a jump line could be worth more here than a third ant."),
 strength2:decision("Count a real reinforcement","Which move adds a second usable attacker?",[
   ["The aim","Two liberties remain. A mobile white ant outside the ring can fill either, but cannot occupy both."],
   ["Available resources","Another ant already holds a side. A reserve hopper can be placed on a line to one gap. A reserve beetle cannot approach either gap in the time available."]],
   [["Deploy the hopper on the jump line.","It gives the existing free ant a different gap to finish."],["Move the ant that already holds a side into a gap.","That ant opens its old side as it fills the new one."],["Count the distant beetle as already attacking.","It needs extra approach moves before it can contribute."]],"After each candidate, count distinct bugs that can fill distinct gaps without reopening a side.","A placement adds effective strength when the new piece has both a route and enough time to use it."),
 replacePin:decision("Hand a pin to a slower bug","What should the ant do once the replacement is ready?",[
   ["Before","A white ant is tied down holding a black beetle in a One Hive pin."],
   ["Now","A white spider has taken over the pin. If the ant leaves, the black beetle still cannot lift. The ant can reach an open queen liberty from outside the ring."]],
   [["Use the ant elsewhere while the spider maintains the pin.","The pin survives and the mobile ant takes on a second job."],["Keep both bugs there because either departure breaks every pin.","The spider already supplies the connection that immobilises the beetle."],["Cover the beetle with the spider.","A spider cannot climb onto an occupied tile."]],"Lift the ant mentally and test the black beetle before choosing.","Replacing the pinning piece can recover an ant's long-range movement without releasing its target."),
 race:decision("Count the approach move","White moves first. Which side wins if both follow their stated attacking lines?",[
   ["White","Two liberties to fill. Place a reserve hopper, jump it into the first gap on the following White turn, then move an ant into the second."],
   ["Black","Two liberties to fill. Two bugs are already in range and can fill one per Black turn. Neither line interferes with the other."]],
   [["Black wins on its second turn.","The order is White places, Black fills, White jumps, Black finishes."],["White wins because it moves first.","White spends its first move preparing an attacker."],["It is a draw because both queens have two liberties.","Equal liberty counts do not imply equal move counts."]],"Write out alternating plies and include the reserve placement.","White needs three turns and Black needs two. An uninterrupted race loses for White, so White should investigate a defence."),
 raceDef:decision("Decide when to defend","White can threaten a win next turn. What should White do now?",[
   ["White’s attack","The best attacking move leaves the black queen with one liberty. White has no immediate win."],
   ["Black’s threat","Black can finish on its next turn. A white pin removes the only finisher and leaves Black without an alternative immediate win."]],
   [["Pin the finisher now.","It changes the next Black turn and keeps the game alive."],["Create the threat against the black queen.","Black can finish immediately and ignore the threat."],["Deploy another long-range ant.","The new ant never gets its next turn if Black takes the win."]],"Compare the actual order in which the two finishes would occur.","A counterattack buys time only when the opponent has to answer it. Here the pin is the move that changes the race."),
 pairChoice:decision("Coordinate the two beetles","Which plan preserves the threat of a direct reserve drop?",[
   ["White’s position","A white beetle covers the black queen. One empty neighbour of the stack touches no other occupied cell except that stack."],
   ["Black’s defender","A mobile black ant can interfere next turn. Your second white beetle can cover it now."]],
   [["Cover the ant with the second beetle.","Both the queen cover and the white contact for the drop survive."],["Leave the queen with the first beetle to cover the ant.","The stack on the queen loses its white top, so the planned reserve entry disappears."],["Place the reserve bug on top of the ant.","A reserve piece must enter on an empty cell."]],"Check what colour the queen's stack would show after each candidate.","The value of the pair is that one beetle can neutralise a defender while the other keeps a deployment route open."),
 shutChoice:decision("Find the missing reply","Black has no movable bug on the board. Is Black shut out?",[
   ["Queen and board","Black's queen is in play. Every black bug on the board is pinned or covered."],
   ["Reserve","Black still has a spider. One empty cell touches a black top piece and no white top pieces."]],
   [["No. Black can place the spider.","That cell is a legal reserve entry."],["Yes. Black must pass.","A legal placement counts as a turn even when no board piece can move."],["Yes. A shutout ends the game immediately.","A shutout would force a pass. A surround ends the game."]],"Inspect reserve pieces and entry cells separately.","Movement and placement are two different sources of legal replies. A shutout must eliminate both."),
 drawCheck:decision("Check the vacated side","What is the result of this proposed jump?",[
   ["Before the move","Both queens have one liberty, the same empty cell. A white hopper stands beside only the black queen."],
   ["The jump","The hopper legally lands in the shared cell. Its original cell becomes empty. Every other occupied neighbour stays occupied."]],
   [["Black wins. Only the white queen is surrounded.","The departure reopens one side of Black's queen."],["A draw. The hopper landed next to both queens.","The departure and the landing must both be counted."],["White wins. White made the surrounding move.","A move can surround its own queen and lose."]],"Recount both rings after removing the hopper from its original space.","Filling a shared last liberty can lose instead of draw when the mover vacates a side of only the opposing queen."),
 squeeze1:decision("Find a waiting move","Which line forces Black to leave a defensive square?",[
   ["Black’s resources","Black has no reserves. Its only legal move is to take a beetle off the last defensive square; all of that beetle's legal destinations abandon the defence."],
   ["White’s choice","White can play a quiet move that preserves these facts, or attack immediately and release a second black piece with a harmless reply."]],
   [["Play the quiet move and give Black the turn.","Black has a legal move and must play it."],["Attack immediately because a threat is always faster.","Releasing the other bug gives Black a waiting move."],["Wait for Black to pass voluntarily.","Black cannot pass while it has a legal move."]],"Count harmless replies after each of White's candidates.","A squeeze relies on the obligation to move. Preserving the opponent's lack of useful choices can matter more than making a new threat."),
 squeeze2:decision("Test a supposed squeeze","Which discovery refutes the claim that Black must move its defender now?",[
   ["Proposed line","White has played a waiting move. Black's only movable board piece is the defender that White wants to dislodge."],
   ["Check the reserve","Black still has an unplayed spider and one legal placement that leaves the defence intact."]],
   [["Black can spend this turn placing the spider.","The harmless legal reply breaks the immediate squeeze."],["Black can always pass when a defence is threatened.","Passing is unavailable while there is any legal action."],["Black loses as soon as only one board piece can move.","Having few movable pieces is not a loss condition."]],"Include legal entries in the list of replies.","A squeeze must survive the opponent's best waiting move. A spare reserve placement can buy an entire turn."),
 psych1:decision("Recheck after a surprise","A stronger opponent leaves their queen one move from surround. What should decide your move?",[
   ["First impression","The exposed liberty looks like bait."],["Available check","Your candidate is a legal ant move from outside both rings. After it lands, the black queen has six occupied neighbours and yours has four."]],
   [["Play the checked surround.","The game ends before the opponent gets a reply."],["Decline it because a stronger player must have a trap.","The resulting position already decides the game."],["Spend a move pinning the opposing ant first.","That gives away the opportunity to finish immediately."]],"Evaluate the resulting six sides before interpreting your opponent's intent.","A concrete terminal position settles the decision even when the opponent's move is surprising."),
 psych2:decision("Use a clock-pressure check","With little time, what should you check before playing your planned attack?",[
   ["Last turn","Black moved a piece that used to pin its own hopper. The hopper now has a line to your queen's last liberty."],
   ["Your plan","Your prepared move would set up a win one turn later, without removing that jump. A legal cover can stop the hopper now."]],
   [["Recheck the newly freed hopper and cover it.","The earlier calculation used a position in which the hopper could not jump."],["Trust the original line since the queens did not move.","The available attackers changed even though the queen cells did not."],["Recount only the empty sides of Black's queen.","That misses the newly available immediate loss at home."]],"Ask what became possible when the opponent lifted their last piece.","A quick scan for newly freed bugs catches a threat that a liberty count alone misses."),
 mos1:decision("Borrow the next ability","How can the white Mosquito set up a climb on its next turn?",[
   ["Now","The ground-level Mosquito touches a white Ant. The marked landing next to a black Beetle is reachable by a legal Ant slide."],
   ["On arrival","No Beetle touches the Mosquito's starting cell. Assume the black Beetle stays adjacent and the Mosquito remains free."]],
   [["Slide to the marked landing now, then copy the Beetle on the next turn.","The two abilities are used on separate turns."],["Slide to the landing and climb in the same turn.","A single move uses one movement pattern."],["Stay beside the Ant and copy the distant Beetle.","A ground-level Mosquito needs an adjacent top piece as its source."]],"Look at the Mosquito's neighbours at the start of each of its turns.","Conversion changes the ability available at the new cell. It takes one move to reposition and a later move to climb.",
   {tiles:{"0,1":["wM1"],"0,0":["wA1"],"1,0":["bG1"],"2,0":["bB1"]},cell:"2,1",target:"wM1"}),
 mos2:decision("Read a Mosquito on a stack","How does the white Mosquito move from this stack?",[
   ["Height","The white Mosquito is already on top of a black ant."],["Neighbours","A ground-level ant is adjacent. No neighbouring top piece is a Beetle."]],
   [["As a Beetle until it returns to ground level.","The height rule determines its movement."],["As an Ant because one is adjacent.","An elevated Mosquito uses Beetle movement."],["It is stranded until a Beetle arrives.","An elevated Mosquito does not need an adjacent Beetle to move as one."]],"Check height before checking the surrounding species.","A Mosquito atop the hive keeps Beetle movement even if the piece that enabled its climb moves away.",
   {tiles:{"0,0":["bA1","wM1"],"1,0":["wA1"],"1,-1":["bQ1"]},target:"wM1"}),
 lady1:decision("Bend over the hive","The gold ring is empty. Which route can the white Ladybug take to it?",[
   ["Local position","All occupied cells in this route are one tile high. The Ladybug is free to lift."],
   ["Landmarks","The first occupied cell is a white ant. The next is a black hopper. The gold ring lies beyond the hopper."]],
   [["Onto the ant, across the hopper, then down to the ring.","The route uses two occupied cells and an empty landing."],["Onto the ant, down beside it, then slide to the ring.","The second step must also be on top of the hive."],["Across the ant and hopper, stopping on the hopper.","The third step must land on the ground."]],"Count occupied, occupied, empty. The route may turn.","The Ladybug can approach around a bend. Trace all three steps before counting it as a finisher.",
   {tiles:{"0,0":["wL1"],"1,0":["wA1"],"1,1":["bG1"]},cell:"2,1",target:"wL1"}),
 lady2:decision("Reject the short route","Which candidate approach to a gated liberty is usable by a Ladybug?",[
   ["Route A","One step onto an occupied cell, then directly down into the liberty."],["Route B","Two steps across distinct occupied cells, then down into the liberty. The hive stays connected and all height gates are clear."],["Route C","Two steps along empty perimeter cells, then a climb onto the hive."]],
   [["Route B.","It satisfies both the length and the height sequence."],["Route A.","The landing would come one step too early."],["Route C.","The first two steps must be above the hive and the last must descend."]],"Work backwards from the empty landing and find two occupied stepping stones.","A nearby gap can still be out of reach when the required second occupied stepping stone is missing."),
 pill1:decision("Rescue the queen","The white queen cannot slide out. Which resource can give her more liberties?",[
   ["Position","A white Pillbug on the ground is adjacent to the single, uncovered white queen. An empty cell on its far side has only one occupied neighbour."],["Lift check","The queen can be lifted without splitting the hive. Both height gates are clear, neither piece was just played or stunned, and both queens are already down."]],
   [["Use the Pillbug to relocate the queen to the far cell.","The queen can be carried over the Pillbug even though her own slide is blocked."],["Slide the queen through the closed ground gate.","The queen's normal movement still obeys that gate."],["Move the Pillbug away and carry the queen with it.","The Pillbug stays put when using its special action."]],"Distinguish the queen's own movement from being moved by the Pillbug.","A Pillbug can rescue an otherwise trapped queen when both lift and landing are legal.",
   {tiles:{"0,0":["wQ1"],"1,0":["wP1"],"0,1":["bS1"],"-1,1":["bG1"],"-1,0":["wA1"],"0,-1":["bA1"]},cell:"2,0",target:"wQ1"}),
 pill2:decision("Check the previous turn","Can Black immediately undo this white rescue with its own Pillbug?",[
   ["White’s last turn","A white Pillbug relocated the white queen. She is now beside a black Pillbug."],["Black’s turn","The black Pillbug has a clear route to an empty landing and both pieces are single and uncovered."]],
   [["No. The just-relocated queen cannot be moved again immediately.","The previous turn matters even when the geometry is legal."],["Yes. Black's Pillbug has a clear route.","A clear lift path does not remove the one-turn restriction."],["Yes, but only if Black moves the queen back to her old cell.","Choosing her old cell gives no exception."]],"Check which tile was moved on the immediately preceding turn.","Before judging a rescue or a counter-lift, check both the diagram and the last move.")
});

